def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    write_time = {}
    results = []

    for op in ops:
        t = op[1]

        # Remove expired entries
        expired_keys = []
        for key in cache:
            if write_time[key] + ttl <= t:
                expired_keys.append(key)

        for key in expired_keys:
            del cache[key]
            del write_time[key]

        if op[0] == 'put':
            key = op[2]
            value = op[3]

            # If key exists, remove it (will re-add at end)
            if key in cache:
                del cache[key]
            # If cache is at capacity and key is new, evict LRU
            elif len(cache) >= capacity:
                lru_key = next(iter(cache))
                del cache[lru_key]
                del write_time[lru_key]

            cache[key] = value
            write_time[key] = t

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                value = cache[key]
                # Move to end (most recently used)
                del cache[key]
                cache[key] = value
                results.append(value)
            else:
                results.append(-1)

    return results

